import SchemaBuilder from '@pothos/core';
import { pluginName } from './plugin';

const builder = new SchemaBuilder({
  plugins: [pluginName],
  logLabel: 'Request',
});

builder.queryType({
  fields: (t) => ({
    hello: t.string({ resolve: () => 'Hello' }),
    goodbye: t.string({ resolve: async () => 'Goodbye' }),
  }),
});

export const schema = builder.toSchema();

import type { SchemaTypes } from '@pothos/core';
import type { ObserverPlugin } from './plugin';

declare global {
  namespace PothosSchemaTypes {
    interface Plugins<Types extends SchemaTypes> {
      architectureObserver: ObserverPlugin<Types>;
    }

    interface SchemaBuilderOptions<Types extends SchemaTypes> {
      logLabel?: string;
    }
  }
}

import './global-types';
import SchemaBuilder, {
  BasePlugin,
  type PothosOutputFieldConfig,
  type SchemaTypes,
} from '@pothos/core';
import type { GraphQLFieldResolver } from 'graphql';

export class ObserverPlugin<Types extends SchemaTypes> extends BasePlugin<
  Types,
  { resolveCount: number }
> {
  createRequestData(_context: Types['Context']) {
    return { resolveCount: 0 };
  }

  wrapResolve(
    resolver: GraphQLFieldResolver<unknown, Types['Context'], object>,
    _fieldConfig: PothosOutputFieldConfig<Types>,
  ): GraphQLFieldResolver<unknown, Types['Context'], object> {
    return (parent, args, context, info) => {
      const data = this.requestData(context);
      data.resolveCount += 1;
      console.log(
        `${this.builder.options.logLabel}: ${info.parentType}.${info.fieldName} (${data.resolveCount})`,
      );
      return resolver(parent, args, context, info);
    };
  }
}

export const pluginName = 'architectureObserver';
SchemaBuilder.registerPlugin(pluginName, ObserverPlugin);
